use trie::Trie;

#[test]
fn test_insert_and_search() {
    let mut t = Trie::new();
    t.insert("apple");
    assert!(t.search("apple"));
    assert!(!t.search("app"));
    assert!(!t.search("apples"));
}

#[test]
fn test_starts_with() {
    let mut t = Trie::new();
    t.insert("apple");
    assert!(t.starts_with("app"));
    assert!(t.starts_with("apple"));
    assert!(!t.starts_with("apz"));
    assert!(!t.starts_with("banana"));
}

#[test]
fn test_prefix_not_word() {
    let mut t = Trie::new();
    t.insert("apple");
    assert!(!t.search("app"));
    t.insert("app");
    assert!(t.search("app"));
    assert!(t.search("apple"));
}

#[test]
fn test_count_words() {
    let mut t = Trie::new();
    assert_eq!(t.count_words(), 0);
    t.insert("hello");
    t.insert("world");
    t.insert("he");
    assert_eq!(t.count_words(), 3);
}

#[test]
fn test_empty_string() {
    let mut t = Trie::new();
    t.insert("");
    assert!(t.search(""));
    assert!(t.starts_with(""));
    assert_eq!(t.count_words(), 1);
}

