Implement Trie in src/lib.rs.

use std::collections::HashMap;

pub struct TrieNode {
    children: HashMap<char, TrieNode>,
    is_end: bool,
}

pub struct Trie {
    root: TrieNode,
}

impl Trie {
    pub fn new() -> Self
    pub fn insert(&mut self, word: &str)          // walk/create nodes per char; mark last as is_end
    pub fn search(&self, word: &str) -> bool      // true iff word was inserted exactly
    pub fn starts_with(&self, prefix: &str) -> bool  // true iff any inserted word has this prefix
    pub fn count_words(&self) -> usize            // recursive count of is_end nodes
}

All 5 tests in tests/trie_test.rs must pass.
Run: cargo test
